<form method="POST" class="card p-4" style="max-width:700px"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token'] ??= bin2hex(random_bytes(32))); ?>"><label class="form-label">Leave type</label><select name="leave_type" class="form-select mb-3"><?php foreach (['Sick','Casual','Annual','Unpaid','Other'] as $type): ?><option><?php echo $type; ?></option><?php endforeach; ?></select><div class="row"><div class="col"><label class="form-label">Start</label><input type="date" name="start_date" class="form-control" required></div><div class="col"><label class="form-label">End</label><input type="date" name="end_date" class="form-control" required></div></div><label class="form-label mt-3">Reason</label><textarea name="reason" class="form-control mb-3" rows="3"></textarea><button class="btn btn-primary">Submit request</button></form>
